import { Suspense } from 'react'
import { prefetch } from 'next/cache'
import { getRelatedProducts } from '@/lib/data'

export default function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        {/* The fallback ships in the App Shell; the list is deferred out of the
            default prefetch and resolved by a <Link prefetch={true}>. */}
        <Suspense fallback={<p>Loading related products…</p>}>
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts() {
  // Keep related products out of the App Shell (the default prefetch every
  // <Link> into this route downloads). A per-link prefetch (<Link prefetch={true}>)
  // or the navigation itself renders them, so they stay cached but are only
  // produced for the links that opt in.
  await prefetch()
  const relatedProducts = await getRelatedProducts()
  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

